function requestsPage(){return `${heading('Solicitudes de compra','Centraliza los requerimientos, controla las aprobaciones y da seguimiento a cada solicitud.',`<button class="btn btn-secondary" data-action="export">${icon('download')} Exportar</button><button class="btn btn-primary" data-action="new-request">${icon('plus')} Nueva solicitud</button>`)}<div class="toolbar"><input class="filter-input" id="tableSearch" placeholder="Buscar por ID, cliente o producto..."><select class="filter-select" id="statusFilter"><option value="Todos">Todos los estados</option><option>Pendiente de aprobación</option><option>En cotización</option><option>Aprobada</option><option>En proceso</option><option>Completada</option></select><select class="filter-select"><option>Todas las categorías</option><option>Aseo e higiene</option><option>Oficina</option><option>Seguridad industrial</option></select><span class="muted" style="font-size:9px;margin-left:auto">${requests.length} solicitudes visibles</span></div><section class="card table-card"><div class="card-header"><div><h3>Listado de solicitudes</h3><p>Información de ejemplo para validar el flujo de compras</p></div><span class="mini-badge">Actualizado ahora</span></div><div id="requestsTable">${tableRequests(requests)}</div></section>`}
function quotesPage(){return `${heading('Cotizaciones','Solicita, recibe y compara propuestas comerciales con criterios homogéneos.',`<button class="btn btn-primary" data-action="new-quote">${icon('plus')} Solicitar cotización</button>`)}<div class="report-kpis"><div class="card report-card"><small>Solicitudes de cotización abiertas</small><strong>18</strong><span>6 esperando respuesta</span></div><div class="card report-card"><small>Ofertas recibidas este mes</small><strong>74</strong><span>+14% vs. octubre</span></div><div class="card report-card"><small>Ahorro promedio comparado</small><strong>8,7%</strong><span>En compras comparables</span></div></div><section class="card table-card"><div class="card-header"><div><h3>Comparativos recientes</h3><p>Resumen de propuestas recibidas por TIARE</p></div><button class="text-link" data-action="compare-quotes">Abrir comparador →</button></div><div class="table-scroll"><table><thead><tr><th>Solicitud</th><th>Proveedor A</th><th>Proveedor B</th><th>Proveedor C</th><th>Mejor costo total</th><th>Estado</th><th></th></tr></thead><tbody><tr><td><div class="id-cell">SOL-2026-0248</div><div class="cell-sub">Insumos de limpieza</div></td><td>$1.840.000</td><td>$1.765.000</td><td>$1.920.000</td><td class="compare-best">$1.765.000</td><td>${status('En cotización')}</td><td><button class="text-link" data-action="compare-quotes">Comparar</button></td></tr><tr><td><div class="id-cell">SOL-2026-0247</div><div class="cell-sub">Elementos de protección</div></td><td>$3.260.000</td><td>$3.410.000</td><td>$3.185.000</td><td class="compare-best">$3.185.000</td><td>${status('Pendiente de aprobación')}</td><td><button class="text-link" data-action="compare-quotes">Comparar</button></td></tr><tr><td><div class="id-cell">SOL-2026-0246</div><div class="cell-sub">Material de oficina</div></td><td>$685.000</td><td>$712.000</td><td>—</td><td class="compare-best">$685.000</td><td>${status('Aprobada')}</td><td><button class="text-link" data-action="compare-quotes">Ver</button></td></tr></tbody></table></div></section><div class="form-note">El comparador debe considerar costo total, impuestos, despacho, garantía, plazo, especificaciones y condiciones de pago. El menor precio unitario no implica automáticamente la mejor oferta.</div>`}
function tendersPage(){return `${heading('Mercado Público','Monitor de oportunidades y apoyo documental para empresas proveedoras del Estado.',`<button class="btn btn-secondary" data-action="tender-filters">${icon('settings')} Configurar alertas</button><button class="btn btn-primary" data-action="refresh-tenders">${icon('sparkles')} Actualizar oportunidades</button>`)}<div class="report-kpis"><div class="card report-card"><small>Oportunidades coincidentes</small><strong>12</strong><span>En categorías monitoreadas</span></div><div class="card report-card"><small>Próximos cierres · 7 días</small><strong>5</strong><span>Requieren evaluación</span></div><div class="card report-card"><small>Monto referencial publicado</small><strong>$82,7 MM</strong><span>No equivale a adjudicaciones</span></div></div><div class="toolbar"><input class="filter-input" id="tenderSearch" placeholder="Buscar organismo, ID o palabra clave..."><select class="filter-select"><option>Todas las regiones</option><option>Metropolitana</option><option>Valparaíso</option></select><select class="filter-select"><option>Todas las categorías</option><option>Aseo</option><option>Seguridad</option><option>Oficina</option></select><span class="chip">Datos demostrativos · no conectados a ChileCompra</span></div><div class="tender-card-grid" id="tenderGrid">${tenders.map(tenderCard).join('')}</div><div class="form-note section-gap"><strong>Nota operativa:</strong> las oportunidades mostradas son ficticias y solo ilustran la interfaz. En producción se consultará la API oficial de Mercado Público, se registrará fecha de consulta y se comprobarán bases y anexos en el portal antes de emitir recomendaciones.</div>`}
function tenderCard(t){return `<article class="card tender-card"><div class="tender-meta"><span class="tender-code">${t.id}</span>${status(t.status)}</div><h3>${t.title}</h3><div class="tender-org">${t.org} · Región de ${t.region}</div><div class="tender-data"><div><span>Presupuesto referencial</span><strong>${money(t.amount)}</strong></div><div><span>Fecha de cierre</span><strong>${shortDate(t.close)}</strong></div></div><div class="tender-footer"><span class="deadline">${icon('clock')} Cierre próximo</span><button class="text-link" data-action="tender-detail" data-id="${t.id}">Analizar oportunidad →</button></div></article>`}
function suppliersPage(){return `${heading('Proveedores','Administra tu red de suministro, desempeño, documentación y cobertura territorial.',`<button class="btn btn-primary" data-action="new-supplier">${icon('plus')} Registrar proveedor</button>`)}<div class="report-kpis"><div class="card report-card"><small>Proveedores registrados</small><strong>186</strong><span>En 12 categorías</span></div><div class="card report-card"><small>Proveedores verificados</small><strong>142</strong><span>76,3% del total</span></div><div class="card report-card"><small>Evaluación promedio</small><strong>4,6 / 5</strong><span>Según entregas registradas</span></div></div><div class="toolbar"><input class="filter-input" id="supplierSearch" placeholder="Buscar proveedor o categoría..."><select class="filter-select"><option>Todas las categorías</option><option>Aseo e higiene</option><option>Seguridad industrial</option><option>Insumos clínicos</option><option>Logística</option></select><select class="filter-select"><option>Todos los estados</option><option>Verificado</option><option>En revisión</option><option>Pendiente</option></select></div><section class="card table-card"><div class="card-header"><div><h3>Directorio de proveedores</h3><p>Ficha, rubros, cobertura y desempeño</p></div><span class="chip">Red de proveedores TIARE</span></div><div class="table-scroll"><table><thead><tr><th>Proveedor</th><th>Categoría</th><th>Región</th><th>Órdenes</th><th>Evaluación</th><th>Estado</th><th></th></tr></thead><tbody id="suppliersBody">${supplierRows()}</tbody></table></div></section>`}
function supplierRows(){return suppliers.map(s=>`<tr><td><div class="supplier-cell"><span class="supplier-logo">${s.initials}</span><div><div class="cell-main">${s.name}</div><div class="cell-sub">${s.id}</div></div></div></td><td>${s.category}</td><td>${s.region}</td><td>${s.orders}</td><td><span class="rating">★</span> ${s.rating.toFixed(1)}</td><td>${status(s.status)}</td><td><button class="table-action" data-action="supplier-detail" data-id="${s.id}">···</button></td></tr>`).join('')}
function clientsPage(){return `${heading('Clientes','Gestiona relaciones comerciales, segmentos, contratos y oportunidades de crecimiento.',`<button class="btn btn-primary" data-action="new-client">${icon('plus')} Agregar cliente</button>`)}<div class="report-kpis"><div class="card report-card"><small>Clientes activos</small><strong>${clients.filter(c=>c.status==='Activo').length+42}</strong><span>+8 incorporados este trimestre</span></div><div class="card report-card"><small>Ingreso recurrente mensual</small><strong>$8,4 MM</strong><span>MRR ilustrativo</span></div><div class="card report-card"><small>Retención de clientes</small><strong>96,2%</strong><span>Últimos 90 días</span></div></div><div class="toolbar"><input id="clientSearch" class="filter-input" placeholder="Buscar empresa, contacto o correo..."><select class="filter-select"><option>Todos los segmentos</option><option>Salud</option><option>Educación</option><option>Construcción</option><option>Proveedor Estado</option><option>Industria</option></select><select class="filter-select"><option>Todos los estados</option><option>Activo</option><option>Prospecto</option></select></div><section class="card table-card"><div class="card-header"><div><h3>Directorio de clientes</h3><p>Organizaciones que contratan servicios TIARE</p></div><span class="mini-badge">${clients.length} registros demo</span></div><div class="table-scroll"><table><thead><tr><th>Organización</th><th>Segmento</th><th>Contacto principal</th><th>Plan</th><th>Gasto gestionado</th><th>Estado</th><th></th></tr></thead><tbody id="clientsBody">${clientRows()}</tbody></table></div></section>`}
function clientRows(){return clients.map(c=>`<tr><td><div class="cell-main">${c.name}</div><div class="cell-sub">${c.id} · ${c.email}</div></td><td><span class="chip">${c.segment}</span></td><td>${c.contact}</td><td>${c.plan}</td><td class="money">${money(c.spend)}</td><td>${status(c.status)}</td><td><button class="table-action" data-action="client-detail" data-id="${c.id}">···</button></td></tr>`).join('')}
function logisticsPage(){return `${heading('Logística y abastecimiento','Coordina despachos, operadores, recepciones y cumplimiento de entregas.',`<button class="btn btn-secondary" data-action="export">${icon('download')} Reporte de entregas</button><button class="btn btn-primary" data-action="new-delivery">${icon('plus')} Programar entrega</button>`)}<div class="report-kpis"><div class="card report-card"><small>Entregas en tránsito</small><strong>14</strong><span>4 llegan hoy</span></div><div class="card report-card"><small>Entregas a tiempo</small><strong>94,6%</strong><span>Meta operacional: 95%</span></div><div class="card report-card"><small>Incidencias abiertas</small><strong>3</strong><span class="trend-down">2 requieren seguimiento</span></div></div><section class="card table-card"><div class="card-header"><div><h3>Seguimiento de despachos</h3><p>Rutas y órdenes coordinadas por TIARE Logistics</p></div><span class="chip">Operadores propios y asociados</span></div><div class="route-row"><span class="route-id">DES-2026-0184</span><div class="route-name"><strong>Centro Médico Los Robles</strong><small>Distribuidora EcoClean · Santiago Centro → Providencia</small><div class="logistics-progress" style="margin-top:7px"><i style="width:80%"></i></div></div><span class="route-driver">Ruta 5 Express</span><span>${status('En tránsito')}</span></div><div class="route-row"><span class="route-id">DES-2026-0183</span><div class="route-name"><strong>Colegio Nuevo Horizonte</strong><small>Papeles y Más · San Bernardo → La Cisterna</small><div class="logistics-progress" style="margin-top:7px"><i style="width:100%"></i></div></div><span class="route-driver">Flota asociada</span><span>${status('Entregado')}</span></div><div class="route-row"><span class="route-id">DES-2026-0182</span><div class="route-name"><strong>Laboratorio Clínico Vital</strong><small>Suministros Médicos Central · Santiago → Ñuñoa</small><div class="logistics-progress" style="margin-top:7px"><i style="width:55%"></i></div></div><span class="route-driver">Ruta 5 Express</span><span>${status('En tránsito')}</span></div><div class="route-row"><span class="route-id">DES-2026-0181</span><div class="route-name"><strong>Constructora Andes Sur</strong><small>Comercial ProSafe · Quilicura → San Bernardo</small><div class="logistics-progress" style="margin-top:7px"><i style="width:100%"></i></div></div><span class="route-driver">Flota propia</span><span>${status('Entregado')}</span></div></section><div class="split-panels section-gap"><section class="card summary-panel"><h3>Modelo de operación mixto</h3><div class="summary-line"><span>Flota y recursos propios</span><strong>35%</strong></div><div class="summary-line"><span>Transportistas asociados</span><strong>65%</strong></div><div class="summary-line"><span>Entregas con evidencia digital</span><strong>91%</strong></div></section><section class="card summary-panel"><h3>Alertas operacionales</h3><div class="summary-line"><span>Entrega sin confirmación de recepción</span>${status('Pendiente')}</div><div class="summary-line"><span>Reintento de despacho por coordinar</span>${status('En proceso')}</div><div class="summary-line"><span>Documento de transporte por adjuntar</span>${status('Pendiente')}</div></section></div>`}
const agentData=[['Procurement Intelligence','Analiza requerimientos, categorías y alternativas de abastecimiento.','sparkles','Activo','Consultas y análisis'],['Tender Intelligence','Monitorea oportunidades públicas y extrae requisitos desde bases.','landmark','Activo','Lectura y clasificación'],['Supplier Intelligence','Compara antecedentes, cobertura y desempeño de proveedores.','users','Activo','Evaluación asistida'],['Quote Analyst','Normaliza ofertas y compara costo total de adquisición.','scale','Activo','Extracción documental'],['Cost Intelligence','Modela costos, márgenes, presupuesto y ahorro verificable.','wallet','Activo','Cálculos controlados'],['Inventory Intelligence','Sugiere reposición y detecta riesgo de quiebre de stock.','package','En preparación','Pronóstico'],['Logistics Intelligence','Analiza rutas, entregas, retrasos e incidencias.','route','En preparación','Optimización'],['Compliance Intelligence','Identifica brechas documentales y alertas normativas.','check','En preparación','Checklist y alertas'],['Business Intelligence','Consolida KPI, tendencias y reportes ejecutivos.','chart','Activo','Análisis de datos']];
function agentsPage(){return `${heading('Agentes IA','Asistentes especializados que colaboran bajo reglas, permisos y aprobación humana.',`<button class="btn btn-secondary" data-action="agent-runs">${icon('clock')} Historial de ejecuciones</button><button class="btn btn-primary" data-action="agent-run-all">${icon('sparkles')} Ejecutar diagnóstico</button>`)}<div class="card ai-mini" style="margin-bottom:15px"><div class="ai-header"><span class="ai-orb">${icon('sparkles')}</span><h3>Orquestador TIARE</h3><span class="status approved" style="margin-left:auto">Operativo · demo</span></div><p>Recibe solicitudes, selecciona agentes y consolida recomendaciones. Las acciones sensibles permanecen sujetas a autorización humana.</p><button data-action="agent-run-all">Simular análisis integral →</button></div><div class="agent-grid">${agentData.map((a,i)=>`<article class="card agent-card"><div class="agent-head"><span class="agent-icon">${icon(a[2])}</span><span class="agent-state" style="${a[3]==='En preparación'?'background:#fff5e5;color:#a9792c':''}">${a[3]}</span></div><h3>${a[0]}</h3><p>${a[1]}</p><div class="agent-foot"><small>${a[4]}</small><button data-action="run-agent" data-agent="${a[0]}">Ejecutar demo</button></div></article>`).join('')}</div><div class="form-note section-gap">Gobierno de IA: las recomendaciones deben mostrar sus fuentes y supuestos. Ningún agente puede aprobar pagos, firmar contratos, adjudicar licitaciones, presentar ofertas ni emitir órdenes sin autorización.</div>`}
function reportsPage(){return `${heading('Analítica e informes','Indicadores para medir eficiencia, ahorro, cumplimiento de proveedores y salud del negocio.',`<button class="btn btn-secondary" data-action="export">${icon('download')} Descargar informe</button><button class="btn btn-primary" data-action="report-generate">${icon('sparkles')} Generar resumen IA</button>`)}<div class="report-kpis"><div class="card report-card"><small>Compras gestionadas YTD</small><strong>$486,2 MM</strong><span>+18,4% vs. año anterior</span></div><div class="card report-card"><small>Ahorro verificado YTD</small><strong>$42,6 MM</strong><span>8,76% sobre costo comparable</span></div><div class="card report-card"><small>Margen bruto estimado</small><strong>42,1%</strong><span>Meta interna: 45%</span></div></div><div class="content-grid"><section class="card chart-card"><div class="card-header"><div><h3>Gasto gestionado por mes</h3><p>Millones de pesos chilenos · datos demostrativos</p></div><select class="mini-select"><option>2026</option><option>2025</option></select></div>${chartSvg()}</section><section class="card category-card"><div class="card-header"><div><h3>Desempeño operacional</h3><p>Indicadores de servicio</p></div></div><div class="category-list">${[['Entregas a tiempo',94.6,'94,6%'],['Cotizaciones comparadas',88,'88%'],['Recepciones conformes',97,'97%'],['Solicitudes dentro de SLA',91,'91%']].map(x=>`<div class="category-row"><span>${x[0]}</span><div class="progress-track"><div class="progress-fill" style="width:${x[1]}%"></div></div><strong>${x[2]}</strong></div>`).join('')}</div></section></div><div class="split-panels"><section class="card summary-panel"><h3>Ingresos por línea de negocio</h3><div class="summary-line"><span>Procurement externalizado</span><strong>$34,8 MM</strong></div><div class="summary-line"><span>Software SaaS</span><strong>$15,0 MM</strong></div><div class="summary-line"><span>Servicios TIARE Public</span><strong>$21,5 MM</strong></div><div class="summary-line"><span>Logística</span><strong>$13,3 MM</strong></div></section><section class="card summary-panel"><h3>Calidad de información</h3><div class="summary-line"><span>Proveedores con ficha completa</span><strong>76%</strong></div><div class="summary-line"><span>Órdenes con recepción adjunta</span><strong>91%</strong></div><div class="summary-line"><span>Compras con 3+ ofertas comparables</span><strong>68%</strong></div><div class="summary-line"><span>Registros pendientes de revisión</span><strong>14</strong></div></section></div>`}
function settingsPage(){return `${heading('Configuración','Administra la organización, los permisos y las preferencias generales del workspace.')}<div class="settings-grid"><div class="card settings-menu"><button class="active">General</button><button>Usuarios y permisos</button><button>Notificaciones</button><button>Integraciones</button><button>Seguridad y auditoría</button><button>Facturación</button></div><section class="card settings-content"><h3>Preferencias de la organización</h3><p>Información general de Tiare Culo Rico SpA.</p><div class="form-grid"><div class="form-field"><label>Razón social</label><input class="form-control" value="Tiare Culo Rico SpA"></div><div class="form-field"><label>Nombre comercial</label><input class="form-control" value="TIARE"></div><div class="form-field"><label>País</label><input class="form-control" value="Chile"></div><div class="form-field"><label>Moneda base</label><input class="form-control" value="CLP — Peso chileno"></div><div class="form-field"><label>Zona horaria</label><input class="form-control" value="America/Santiago"></div><div class="form-field"><label>Correo de contacto</label><input class="form-control" value="contacto@tiare.cl"></div></div><div class="setting-row section-gap"><div><strong>Notificaciones de aprobaciones</strong><small>Alertar cuando una solicitud requiera autorización.</small></div><button class="toggle on" aria-label="Alternar notificación"></button></div><div class="setting-row"><div><strong>Registro de auditoría</strong><small>Conservar historial de cambios y acciones críticas.</small></div><button class="toggle on" aria-label="Alternar auditoría"></button></div><div class="setting-row"><div><strong>Asistencia de inteligencia artificial</strong><small>Permitir recomendaciones y borradores con revisión humana.</small></div><button class="toggle on" aria-label="Alternar IA"></button></div><div class="form-note">Esta pantalla es una representación visual. Los cambios no se conectan con un backend ni configuran permisos reales.</div><div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="btn btn-primary" data-action="save-settings">Guardar preferencias</button></div></section></div>`}
const renderers={dashboard,requests:requestsPage,quotes:quotesPage,tenders:tendersPage,suppliers:suppliersPage,clients:clientsPage,logistics:logisticsPage,agents:agentsPage,reports:reportsPage,settings:settingsPage};
function render(page){activePage=page;pageContent.innerHTML=(renderers[page]||dashboard)();document.getElementById('breadcrumbTitle').textContent=pageNames[page]||'Resumen ejecutivo';document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));document.getElementById('sidebar').classList.remove('open');document.getElementById('mobileScrim').classList.remove('show');bindPageFilters();window.scrollTo({top:0,behavior:'smooth'});}
function bindPageFilters(){const bind=(id,fn)=>{const el=document.getElementById(id);if(el)el.addEventListener('input',fn)};bind('tableSearch',filterRequests);bind('statusFilter',filterRequests);bind('clientSearch',filterClients);bind('supplierSearch',filterSuppliers);bind('tenderSearch',filterTenders)}
function filterRequests(){const q=(document.getElementById('tableSearch')?.value||'').toLowerCase(),s=document.getElementById('statusFilter')?.value||'Todos';const rows=requests.filter(r=>(s==='Todos'||r.status===s)&&`${r.id} ${r.name} ${r.client} ${r.category}`.toLowerCase().includes(q));document.getElementById('requestsTable').innerHTML=rows.length?tableRequests(rows):'<div class="empty-state"><strong>No hay solicitudes coincidentes</strong>Prueba con otro término o estado.</div>'}
function filterClients(){const q=document.getElementById('clientSearch').value.toLowerCase();const rows=clients.filter(c=>`${c.name} ${c.contact} ${c.email} ${c.segment}`.toLowerCase().includes(q));document.getElementById('clientsBody').innerHTML=rows.length?clientRowsFiltered(rows):'<tr><td colspan="7"><div class="empty-state">No se encontraron clientes.</div></td></tr>'}
function clientRowsFiltered(rows){return rows.map(c=>`<tr><td><div class="cell-main">${c.name}</div><div class="cell-sub">${c.id} · ${c.email}</div></td><td><span class="chip">${c.segment}</span></td><td>${c.contact}</td><td>${c.plan}</td><td>${money(c.spend)}</td><td>${status(c.status)}</td><td><button class="table-action" data-action="client-detail" data-id="${c.id}">···</button></td></tr>`).join('')}
function filterSuppliers(){const q=document.getElementById('supplierSearch').value.toLowerCase();const rows=suppliers.filter(s=>`${s.name} ${s.category} ${s.region}`.toLowerCase().includes(q));document.getElementById('suppliersBody').innerHTML=rows.map(s=>`<tr><td><div class="supplier-cell"><span class="supplier-logo">${s.initials}</span><div><div class="cell-main">${s.name}</div><div class="cell-sub">${s.id}</div></div></div></td><td>${s.category}</td><td>${s.region}</td><td>${s.orders}</td><td><span class="rating">★</span> ${s.rating.toFixed(1)}</td><td>${status(s.status)}</td><td><button class="table-action" data-action="supplier-detail" data-id="${s.id}">···</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty-state">No se encontraron proveedores.</div></td></tr>'}
function filterTenders(){const q=document.getElementById('tenderSearch').value.toLowerCase();document.getElementById('tenderGrid').innerHTML=tenders.filter(t=>`${t.id} ${t.title} ${t.org} ${t.category}`.toLowerCase().includes(q)).map(tenderCard).join('')||'<div class="empty-state"><strong>Sin oportunidades coincidentes</strong>Modifica los filtros de búsqueda.</div>'}
function toast(message){const region=document.getElementById('toastRegion'),node=document.createElement('div');node.className='toast';node.innerHTML='<i></i>'+message;region.appendChild(node);setTimeout(()=>node.remove(),3500)}
function openModal(title,eyebrow,body,buttons){document.getElementById('modalTitle').textContent=title;document.getElementById('modalEyebrow').textContent=eyebrow||'TIARE WORKSPACE';document.getElementById('modalBody').innerHTML=body;document.getElementById('modalFooter').innerHTML=buttons;document.getElementById('modalBackdrop').classList.add('open');document.getElementById('modalBackdrop').setAttribute('aria-hidden','false')}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('open');document.getElementById('modalBackdrop').setAttribute('aria-hidden','true')}
const cancelBtn='<button class="btn btn-secondary" data-action="close-modal">Cancelar</button>';
function newRequest(){openModal('Crear solicitud de compra','NUEVO REQUERIMIENTO',`<form id="requestForm"><div class="form-grid"><div class="form-field full"><label>Nombre del requerimiento *</label><input class="form-control" name="name" required placeholder="Ej. Insumos de limpieza institucional"></div><div class="form-field"><label>Cliente *</label><select class="form-control" name="client" required>${clients.map(c=>`<option>${c.name}</option>`).join('')}</select></div><div class="form-field"><label>Categoría *</label><select class="form-control" name="category"><option>Aseo e higiene</option><option>Seguridad industrial</option><option>Insumos de salud</option><option>Oficina</option><option>Mantención</option><option>Logística</option><option>Otra</option></select></div><div class="form-field"><label>Monto estimado (CLP) *</label><input class="form-control" name="amount" type="number" min="1" required placeholder="850000"></div><div class="form-field"><label>Fecha requerida</label><input class="form-control" name="needed" type="date" value="2026-11-13"></div><div class="form-field full"><label>Descripción / especificaciones</label><textarea class="form-control textarea" name="description" placeholder="Indica cantidades, características, condiciones de entrega..."></textarea></div></div><div class="form-note">Al guardar se creará un registro local con estado “Pendiente de aprobación”. No se enviará ninguna orden a proveedores.</div></form>`,`${cancelBtn}<button class="btn btn-primary" data-action="save-request">Guardar solicitud</button>`)}
function newClient(){openModal('Agregar cliente','CRM / NUEVA ORGANIZACIÓN',`<form id="clientForm"><div class="form-grid"><div class="form-field full"><label>Razón social / organización *</label><input class="form-control" name="name" required placeholder="Nombre de la empresa"></div><div class="form-field"><label>Segmento</label><select class="form-control" name="segment"><option>Pyme</option><option>Salud</option><option>Educación</option><option>Construcción</option><option>Proveedor Estado</option><option>Institución pública</option><option>Industria</option><option>Comercio</option></select></div><div class="form-field"><label>Plan comercial</label><select class="form-control" name="plan"><option>Start</option><option>Growth</option><option>Managed</option><option>Public</option><option>SaaS</option></select></div><div class="form-field"><label>Contacto principal</label><input class="form-control" name="contact" placeholder="Nombre y apellido"></div><div class="form-field"><label>Correo electrónico</label><input class="form-control" type="email" name="email" placeholder="contacto@empresa.cl"></div></div></form>`,`${cancelBtn}<button class="btn btn-primary" data-action="save-client">Guardar cliente</button>`)}
function newSupplier(){openModal('Registrar proveedor','RED DE ABASTECIMIENTO',`<form id="supplierForm"><div class="form-grid"><div class="form-field full"><label>Razón social *</label><input class="form-control" name="name" required placeholder="Nombre del proveedor"></div><div class="form-field"><label>Categoría</label><select class="form-control" name="category"><option>Aseo e higiene</option><option>Seguridad industrial</option><option>Insumos clínicos</option><option>Oficina</option><option>Logística</option><option>Mantención</option><option>Otra</option></select></div><div class="form-field"><label>Región</label><select class="form-control" name="region"><option>Metropolitana</option><option>Valparaíso</option><option>O’Higgins</option><option>Biobío</option><option>La Araucanía</option><option>Otra</option></select></div><div class="form-field"><label>Correo de contacto</label><input class="form-control" name="email" type="email" placeholder="ventas@proveedor.cl"></div><div class="form-field"><label>Teléfono</label><input class="form-control" name="phone" placeholder="+56 9 ..."></div></div><div class="form-note">El registro no valida por sí mismo la habilitación legal, tributaria o técnica del proveedor. La verificación documental debe realizarse por separado.</div></form>`,`${cancelBtn}<button class="btn btn-primary" data-action="save-supplier">Guardar proveedor</button>`)}
function compareQuotes(){openModal('Comparador de cotizaciones','ANÁLISIS DE COSTO TOTAL',`<p class="subtle-note" style="margin:0 0 12px">Solicitud SOL-2026-0248 · Insumos de limpieza institucional · Comparación ilustrativa.</p><div class="table-scroll"><table class="compare-table"><thead><tr><th>Criterio</th><th>EcoClean</th><th>Higiene Total</th><th>Distrib. Norte</th></tr></thead><tbody><tr><td>Precio neto</td><td>$1.550.000</td><td class="compare-best">$1.485.000</td><td>$1.610.000</td></tr><tr><td>Despacho</td><td>$55.000</td><td>$80.000</td><td>$45.000</td></tr><tr><td>Plazo</td><td>3 días</td><td>5 días</td><td>7 días</td></tr><tr><td>Garantía</td><td>30 días</td><td>30 días</td><td>15 días</td></tr><tr><td>Evaluación</td><td>4,8/5</td><td>4,6/5</td><td>4,2/5</td></tr><tr><td><strong>Costo total neto</strong></td><td>$1.605.000</td><td class="compare-best">$1.565.000</td><td>$1.655.000</td></tr></tbody></table></div><div class="form-note">Recomendación preliminar: Higiene Total presenta el menor costo total estimado. Antes de recomendar adjudicar o comprar, validar especificaciones, impuestos, disponibilidad, calidad, condiciones y autorización del cliente.</div>`,`${cancelBtn}<button class="btn btn-primary" data-action="approve-demo">Registrar recomendación</button>`)}
function detailModal(title,description,extra=''){openModal(title,'VISTA DE DETALLE · DATOS DEMOSTRATIVOS',`<p style="font-size:11px;color:#566d7b;line-height:1.6">${description}</p>${extra}<div class="form-note">Acción de demostración. No se comunica con proveedores, clientes ni plataformas externas.</div>`,`${cancelBtn}<button class="btn btn-primary" data-action="close-modal">Entendido</button>`)}
function handleAction(action,el){switch(action){case'new-request':newRequest();break;case'new-client':newClient();break;case'new-supplier':newSupplier();break;case'compare-quotes':compareQuotes();break;case'new-quote':detailModal('Nueva solicitud de cotización','Selecciona una solicitud aprobada, define los proveedores invitados y fija la fecha límite para responder. En producción este proceso enviará solicitudes mediante correo o portal seguro.');break;case'new-delivery':detailModal('Programar entrega','Elige una orden de compra, operador logístico, dirección de entrega, ventana horaria y persona receptora. La coordinación queda pendiente de confirmación.');break;case'tender-filters':detailModal('Configurar alertas de Mercado Público','Define palabras clave, categorías, regiones, tipos de comprador, presupuesto y periodicidad de consulta. La plataforma debe consultar fuentes oficiales y registrar la fecha de actualización.');break;case'refresh-tenders':toast('Simulación: se actualizaría el monitor desde la API oficial.');break;case'agent-runs':detailModal('Historial de ejecuciones','Aquí se registrarán agente, usuario solicitante, tarea, fuentes consultadas, herramientas utilizadas, duración, resultado, aprobaciones y errores.');break;case'agent-run-all':toast('Orquestador: diagnóstico de demostración iniciado.');setTimeout(()=>toast('Diagnóstico simulado: 3 oportunidades y 2 alertas detectadas.'),900);break;case'run-agent':toast(`${el.dataset.agent}: ejecución de demostración iniciada.`);break;case'report-generate':detailModal('Resumen ejecutivo asistido por IA','El agente BI consolidaría gasto gestionado, ahorro verificable, desviaciones, cumplimiento de proveedores y entregas. Antes de compartir el informe, un responsable revisa cifras y fuentes.');break;case'export':toast('Exportación simulada: en producción se generará un archivo descargable.');break;case'save-settings':toast('Preferencias de demostración guardadas en pantalla.');break;case'close-modal':closeModal();break;case'tender-detail':{const t=tenders.find(x=>x.id===el.dataset.id);if(t)detailModal(t.title,`${t.id} · ${t.org}. Presupuesto referencial ${money(t.amount)}. Cierre ${shortDate(t.close)}. El análisis real debe revisar bases, anexos, requisitos, garantías, criterios de evaluación y consultas/respuestas oficiales.`);break}case'request-detail':{const r=requests.find(x=>x.id===el.dataset.id);if(r)detailModal(r.name,`${r.id} · ${r.client}. Monto estimado: ${money(r.amount)}. Estado: ${r.status}. Responsable: ${r.owner}.`, `<div class="summary-line"><span>Categoría</span><strong>${r.category}</strong></div><div class="summary-line"><span>Fecha de ingreso</span><strong>${shortDate(r.date)}</strong></div>`);break}case'client-detail':{const c=clients.find(x=>x.id===el.dataset.id);if(c)detailModal(c.name,`Contacto: ${c.contact} · ${c.email}. Segmento: ${c.segment}. Plan: ${c.plan}. Gasto gestionado referencial: ${money(c.spend)}.`);break}case'supplier-detail':{const s=suppliers.find(x=>x.id===el.dataset.id);if(s)detailModal(s.name,`Categoría: ${s.category}. Región: ${s.region}. Evaluación: ${s.rating}/5. Órdenes registradas: ${s.orders}. Estado documental: ${s.status}.`);break}case'save-request':saveRequest();break;case'save-client':saveClient();break;case'save-supplier':saveSupplier();break;case'approve-demo':closeModal();toast('Recomendación registrada en esta demostración; la compra sigue pendiente de aprobación.');break}}
function saveRequest(){const form=document.getElementById('requestForm');if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form).entries());const id='SOL-2026-'+String(249+requests.length-initialRequests.length).padStart(4,'0');requests.unshift({id,name:d.name,client:d.client,category:d.category,amount:Number(d.amount),status:'Pendiente de aprobación',date:new Date().toISOString().slice(0,10),owner:'Samuel Toro'});localStorage.setItem('tiare_requests',JSON.stringify(requests));closeModal();if(activePage==='requests')render('requests');else render('dashboard');toast('Solicitud creada correctamente en los datos locales.');}
function saveClient(){const form=document.getElementById('clientForm');if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form).entries());clients.unshift({id:'CLI-'+String(19+clients.length-initialClients.length).padStart(4,'0'),name:d.name,segment:d.segment,contact:d.contact||'Sin asignar',email:d.email||'Sin correo',plan:d.plan,status:'Prospecto',spend:0});localStorage.setItem('tiare_clients',JSON.stringify(clients));closeModal();render('clients');toast('Cliente agregado al CRM local.');}
function saveSupplier(){const form=document.getElementById('supplierForm');if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form).entries());suppliers.unshift({id:'PRV-'+String(76+suppliers.length).padStart(4,'0'),name:d.name,category:d.category,region:d.region,rating:0,orders:0,status:'Pendiente',initials:d.name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()});closeModal();render('suppliers');toast('Proveedor registrado en la demostración.');}

// Delegación de eventos para mantener la maqueta sencilla y portable.
document.addEventListener('click',e=>{
 const toggle=e.target.closest('.toggle');if(toggle){toggle.classList.toggle('on');toast('Preferencia visual actualizada.');return}
 const setting=e.target.closest('.settings-menu button');if(setting){document.querySelectorAll('.settings-menu button').forEach(b=>b.classList.remove('active'));setting.classList.add('active');if(setting.textContent.trim()!=='General')toast('Sección de configuración de demostración.');return}
 const nav=e.target.closest('[data-page]');if(nav){render(nav.dataset.page);return}
 const pageLink=e.target.closest('[data-page-link]');if(pageLink){render(pageLink.dataset.pageLink);return}
 const action=e.target.closest('[data-action]');if(action){handleAction(action.dataset.action,action);return}
 if(e.target.id==='modalBackdrop')closeModal();
});
document.getElementById('modalClose').addEventListener('click',closeModal);
document.getElementById('menuToggle').addEventListener('click',()=>{document.getElementById('sidebar').classList.add('open');document.getElementById('mobileScrim').classList.add('show')});
document.getElementById('sidebarClose').addEventListener('click',()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('mobileScrim').classList.remove('show')});
document.getElementById('mobileScrim').addEventListener('click',()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('mobileScrim').classList.remove('show')});
document.getElementById('notificationButton').addEventListener('click',()=>detailModal('Centro de notificaciones','Tienes 2 solicitudes pendientes de aprobación, 3 entregas por confirmar y 5 oportunidades públicas próximas a cierre.'));
document.getElementById('helpButton').addEventListener('click',()=>toast('Centro de ayuda: contacto de soporte pendiente de configurar.'));
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.trim().toLowerCase();if(!q)return;const found=[['requests',requests.some(r=>`${r.id} ${r.name} ${r.client}`.toLowerCase().includes(q))],['clients',clients.some(c=>`${c.name} ${c.contact}`.toLowerCase().includes(q))],['suppliers',suppliers.some(s=>`${s.name} ${s.category}`.toLowerCase().includes(q))],['tenders',tenders.some(t=>`${t.id} ${t.title} ${t.org}`.toLowerCase().includes(q))]].find(x=>x[1]);if(found){render(found[0]);const field={requests:'tableSearch',clients:'clientSearch',suppliers:'supplierSearch',tenders:'tenderSearch'}[found[0]];const el=document.getElementById(field);if(el){el.value=q;el.dispatchEvent(new Event('input'))}}else toast('No se encontraron coincidencias en los datos de demostración.')}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();const s=document.getElementById('globalSearch');s.focus();if(innerWidth<=650)s.classList.add('expanded')}if(e.key==='Escape')closeModal()});
render('dashboard');
